mapper.sql:
WHERE deleted = 0

    AND (
        company_name LIKE CONCAT('%', #{keyword}, '%')
        OR company_code LIKE CONCAT('%', #{keyword}, '%')
    )


    AND status = #{status}

mapper.select:
SELECT
    COUNT(*) AS count
FROM express_company
WHERE company_name = #{companyName}

    AND id != #{excludeId}

SELECT
    COUNT(*) AS count
FROM express_company
WHERE company_code = #{companyCode}

    AND id != #{excludeId}

mapper.update:
UPDATE express_company
SET status = #{status},
    update_time = #{updateTime}
WHERE id = #{id}
    AND deleted = 0

UPDATE express_company
SET deleted = 1,
    update_time = #{updateTime}
WHERE id = #{id}
    AND deleted = 0
